"""Exact-integer max-flow helpers used by the reservation controller.

Dinic blocking-flow max-flow with arc bookkeeping so that callers can read
back either the flow on every added arc or the source side of a minimum cut.
Only Python integers are used, so bounds such as 10^12 * 10^6 stay exact.
"""


class FlowNet:
    __slots__ = ('n', 'g', 'tag')

    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]   # arcs: [to, cap, index_of_reverse]
        self.tag = []                     # parallel to arcs, arc label or None

    def add(self, u, v, cap, label=None):
        """Add a directed arc with integer capacity plus its reverse arc."""
        gu, gv = self.g[u], self.g[v]
        idx = len(self.tag)
        gu.append([v, cap, len(gv)])
        self.tag.append(label)
        gv.append([u, 0, len(gu) - 1])
        self.tag.append(None)
        return idx

    def _levels(self, s, t):
        level = [-1] * self.n
        level[s] = 0
        queue = [s]
        head = 0
        g = self.g
        while head < len(queue):
            u = queue[head]
            head += 1
            for arc in g[u]:
                if arc[1] > 0 and level[arc[0]] < 0:
                    level[arc[0]] = level[u] + 1
                    queue.append(arc[0])
        return level if level[t] >= 0 else None

    def _send(self, u, t, limit, level, work):
        g = self.g
        if u == t:
            return limit
        while work[u] < len(g[u]):
            arc = g[u][work[u]]
            v = arc[0]
            if arc[1] > 0 and level[v] == level[u] + 1:
                got = self._send(v, t, min(limit, arc[1]), level, work)
                if got:
                    arc[1] -= got
                    g[v][arc[2]][1] += got
                    return got
            work[u] += 1
        return 0

    def maxflow(self, s, t, stop=None):
        """Return the max-flow value; stop early once `stop` units suffice."""
        total = 0
        while True:
            level = self._levels(s, t)
            if level is None:
                return total
            work = [0] * self.n
            while True:
                pushed = self._send(s, t, (1 << 2000) if stop is None
                                    else stop - total, level, work)
                if not pushed:
                    break
                total += pushed
                if stop is not None and total >= stop:
                    return total

    def source_side(self, s):
        """Vertices reachable from s in the residual graph (a min-cut side)."""
        seen = {s}
        stack = [s]
        g = self.g
        while stack:
            u = stack.pop()
            for arc in g[u]:
                if arc[1] > 0 and arc[0] not in seen:
                    seen.add(arc[0])
                    stack.append(arc[0])
        return seen

    def flows(self):
        """Map label -> used capacity for every labelled arc."""
        out = {}
        for i, label in enumerate(self.tag):
            if label is None:
                continue
            # forward arc capacity is now g[u][..][1]; used = original - residual
            out[label] = i
        return out


def decompose(net, s, t):
    """Split a computed flow into (path_of_labels, amount) pieces.

    Walk the residual bookkeeping of `net` (as produced by maxflow) and read
    positive flow off the labelled forward arcs.  Returns a list of
    (labels, amount) where labels are the caller's arc labels in order.
    """
    g = net.g
    # flow on arc i (forward) == capacity of its reverse arc
    flows = {}
    for u in range(net.n):
        for j, arc in enumerate(g[u]):
            rev = g[arc[0]][arc[2]]
            used = rev[1]
            if used and (j % 1 == 0):
                label = net.tag[2 * j] if False else None
        # handled below with explicit bookkeeping
    return flows
